package main

import (
	"crypto/aes"
	"crypto/cipher"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"time"

	"github.com/gorilla/websocket"
)

var (
	encryptionKey = []byte("0123456789abcdef0123456789abcdef") // 32 bytes for AES-256
	upgrader      = websocket.Upgrader{
		CheckOrigin: func(r *http.Request) bool { return true },
	}
)

type Message struct {
	Type    string `json:"type"`
	Payload string `json:"payload"`
	Token   string `json:"token"`
}

type DecryptedPayload struct {
	Action string `json:"action"`
	Data   string `json:"data"`
	TS     int64  `json:"ts"`
}

// pkcs7Unpad removes PKCS#7 padding - VULNERABLE: leaks padding validity via timing/error
func pkcs7Unpad(data []byte) ([]byte, error) {
	if len(data) == 0 {
		return nil, fmt.Errorf("empty data")
	}
	padLen := int(data[len(data)-1])
	if padLen == 0 || padLen > aes.BlockSize {
		return nil, fmt.Errorf("invalid padding length: %d", padLen)
	}
	for i := len(data) - padLen; i < len(data); i++ {
		if data[i] != byte(padLen) {
			return nil, fmt.Errorf("invalid padding byte at position %d", i)
		}
	}
	return data[:len(data)-padLen], nil
}

func decryptPayload(ciphertext []byte) ([]byte, error) {
	if len(ciphertext) < aes.BlockSize {
		return nil, fmt.Errorf("ciphertext too short")
	}

	iv := ciphertext[:aes.BlockSize]
	encrypted := ciphertext[aes.BlockSize:]

	if len(encrypted)%aes.BlockSize != 0 {
		return nil, fmt.Errorf("ciphertext not block-aligned")
	}

	block, err := aes.NewCipher(encryptionKey)
	if err != nil {
		return nil, err
	}

	mode := cipher.NewCBCDecrypter(block, iv)
	plaintext := make([]byte, len(encrypted))
	mode.CryptBlocks(plaintext, encrypted)

	// Padding oracle: different error messages for padding vs. JSON parse
	unpadded, err := pkcs7Unpad(plaintext)
	if err != nil {
		return nil, fmt.Errorf("decryption failed: padding error")
	}
	return unpadded, nil
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	for {
		_, raw, err := conn.ReadMessage()
		if err != nil {
			break
		}

		var msg Message
		if err := json.Unmarshal(raw, &msg); err != nil {
			conn.WriteJSON(map[string]string{"error": "invalid message format"})
			continue
		}

		if msg.Type == "encrypted_command" {
			ciphertext, err := base64.StdEncoding.DecodeString(msg.Payload)
			if err != nil {
				conn.WriteJSON(map[string]string{"error": "invalid base64"})
				continue
			}

			start := time.Now()
			plaintext, err := decryptPayload(ciphertext)
			elapsed := time.Since(start)

			if err != nil {
				// Padding oracle: error response distinguishes padding failure
				// AND timing side-channel leaks padding validity
				conn.WriteJSON(map[string]string{
					"error":   err.Error(),
					"elapsed": elapsed.String(),
				})
				continue
			}

			var payload DecryptedPayload
			if err := json.Unmarshal(plaintext, &payload); err != nil {
				conn.WriteJSON(map[string]string{"error": "invalid payload structure"})
				continue
			}

			conn.WriteJSON(map[string]string{
				"status": "ok",
				"action": payload.Action,
			})
		}
	}
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/ws", handleWebSocket)
	http.HandleFunc("/health", healthCheck)
	log.Println("WebSocket service starting on :8443")
	log.Fatal(http.ListenAndServe(":8443", nil))
}
